import { KeyboardEvent, useRef, useState } from 'react';

type Token = { id: string; label: string };
type Props = { tokens: Token[]; query: string; onChange: (next: { tokens: Token[]; query: string }) => void; suggestions: string[] };
export function TokenizedSearch({ tokens, query, onChange, suggestions }: Props) {
  const input = useRef<HTMLInputElement>(null);
  const [message, setMessage] = useState('');
  const remove = (id: string) => { const next = tokens.filter(t => t.id !== id); onChange({ tokens: next, query }); setMessage('Filter removed'); requestAnimationFrame(() => input.current?.focus()); };
  const keyDown = (event: KeyboardEvent<HTMLInputElement>) => { if (event.key === 'Backspace' && !query && tokens.length) { event.preventDefault(); remove(tokens[tokens.length - 1].id); } };
  return <div><label htmlFor="search-input">Search items and filters</label><div className="token-search" role="search">{tokens.map(token => <span className="token" key={token.id}>{token.label}<button aria-label={`Remove filter ${token.label}`} onClick={() => remove(token.id)}>×</button></span>)}<input ref={input} id="search-input" type="search" value={query} onKeyDown={keyDown} onChange={e => onChange({ tokens, query: e.target.value })} aria-controls="search-suggestions" autoComplete="off" /><button aria-label="Clear search" onClick={() => { onChange({ tokens: [], query: '' }); input.current?.focus(); }}>Clear</button></div><div id="search-suggestions" role="listbox" aria-label="Search suggestions">{suggestions.map(s => <button role="option" key={s} onClick={() => { onChange({ tokens, query: s }); input.current?.focus(); }}>{s}</button>)}</div><p className="sr-only" aria-live="polite">{message}</p></div>;
}
